<?php
$cfgPath = dirname(__DIR__) . '/backend/config/database.local.php';
if (!is_file($cfgPath)) {
    http_response_code(503);
    exit('Website belum dikonfigurasi.');
}
$cfg = require $cfgPath;

try {
    $pdo = new PDO(
        sprintf('mysql:host=%s;dbname=%s;charset=%s', $cfg['host'], $cfg['database'], $cfg['charset'] ?? 'utf8mb4'),
        $cfg['username'],
        $cfg['password'],
        [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]
    );
} catch (Throwable $e) {
    error_log('[STIT WEBSITE] ' . $e->getMessage());
    http_response_code(503);
    exit('Layanan sementara tidak tersedia.');
}

function h(mixed $value): string {
    return htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

$campus = $pdo->query('SELECT * FROM campus_profile WHERE id=1')->fetch() ?: [];
$news = $pdo->query('SELECT id,title,excerpt,body,category,image_url,published_at FROM news_posts WHERE published_at IS NOT NULL AND published_at<=UTC_TIMESTAMP() ORDER BY published_at DESC LIMIT 6')->fetchAll();
$programs = $pdo->query('SELECT code,name,degree_level FROM study_programs WHERE is_active=1 ORDER BY name')->fetchAll();

$campusName = $campus['name'] ?? 'STIT Darul Ilmi Tasikmalaya';
$tagline = $campus['tagline'] ?? 'Membangun Generasi Berilmu, Berakhlak, dan Berdaya Saing';
$about = $campus['about'] ?? 'STIT Darul Ilmi Tasikmalaya hadir sebagai lingkungan pendidikan tinggi yang mendorong tumbuhnya keilmuan, karakter, dan kontribusi nyata bagi masyarakat.';
$pmbUrl = $campus['pmb_url'] ?? '';
?>
